export type TraceSpan = { id: string, parentId: string | null, 
/**
 * `None` for a project the viewer can't see; then `name` and `service` are empty.
 */
projectId: ProjectId | null, service: string, runtime: Runtime, name: string, kind: SpanKind, startMs: number, durationMs: number, status: SpanStatus, statusMessage: string | null, attributes: { [key in string]: string }, event: SpanEvent | null, 
/**
 * The host of a failed call into a service that sent no spans for it.
 */
silent: string | null, };

/**
 * One go at an issue and what came of it.
 */
export type Triage = { id: TriageId, by: Person, 
/**
 * The access token's name when an agent did it.
 */
via: string | null, startedAt: IsoDate, updatedAt: IsoDate, state: TriageState, outcome: TriageOutcome | null, 
/**
 * The cause and what was learned, including data bertha didn't have.
 */
found: string | null, 
/**
 * What was tried that didn't work.
 */
tried: string | null, 
/**
 * The change, with its PR or commit.
 */
fix: string | null, 
/**
 * The release the issue was on when the triage started.
 */
release: string | null, 
/**
 * How the fix is getting to production; `None` unless the outcome is fixed.
 */
watch: FixWatch | null, };

/**
 * Someone on an issue right now.
 */
export type TriageClaim = { by: Person, via: string | null, since: IsoDate, };

/**
 * `active`: being triaged now. `never`: no triage was ever started.
 * `fix_waiting`: not resolved, and the latest triage ended fixed.
 */
export type TriageFilter = "active" | "never" | "fix_waiting";

export type TriageId = string;

/**
 * Fields left out are unchanged. An outcome ends the triage.
 */
export type TriageInput = { found?: string, tried?: string, fix?: string, 
/**
 * The fix's PR on the project's repo; otherwise read from `fix`.
 */
pr?: number, 
/**
 * The fix's commit; otherwise read from `fix`.
 */
commit?: string, outcome?: TriageOutcome, };

export type TriageOutcome = "fixed" | "not_a_bug" | "cant_fix" | "needs_data" | "abandoned";

/**
 * `stale`: active, but with no update for two hours.
 */
export type TriageState = "active" | "stale" | "done";

export type UnsnoozeReason = "date_passed" | "event_threshold";

export type UpdateIssuesFailure = "not_found" | "permission_denied" | "conflict" | "no_fix";

export type UpdateIssuesInput = { issueIds: Array<IssueId>, change: IssueChange, 
/**
 * Optional: when present, enables conflict detection.
 */
seen?: Array<SeenIssue>, };

export type UpdateMemberAccessFailure = "permission_denied";

export type UpdateProjectFailure = "name_taken" | "invalid_name" | "permission_denied";

export type UpdateTriageFailure = "not_found" | "permission_denied" | "concluded";

export type UptimeCheck = { at: IsoDate, ok: boolean, httpStatus: number | null, responseMs: number | null, error: string | null, region: string, };

export type UptimeData = { monitors: Array<Monitor>, projects: Array<Project>, };
